def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def spans(n, cuts):
        result = []
        start = 0
        for cut in cuts:
            if start < cut:
                result.append((start, cut))
            start = cut + 1
        if start < n:
            result.append((start, n))
        return result

    row_spans = spans(h, sep_rows)
    col_spans = spans(w, sep_cols)

    counts = {}
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    v = grid[r][c]
                    counts[v] = counts.get(v, 0) + 1

    background = max(counts, key=counts.get)
    marker = next((v for v in counts if v != background), background)

    return [
        [
            1 if sum(grid[r][c] == marker
                     for r in range(r0, r1)
                     for c in range(c0, c1)) == 2 else background
            for c0, c1 in col_spans
        ]
        for r0, r1 in row_spans
    ]
